    num: int
    den: int = 1
    raw: Optional[z3.RatNumRef] = None

    @property
    def is_zero(self) -> bool:
        return self.num == 0

    @property
    def is_one(self) -> bool:
        return self.num == self.den

    def lower(self) -> z3.RatNumRef:
        if self.raw is not None:
            return self.raw
        return z3.RealVal(f"{self.num}/{self.den}") if self.den != 1 else z3.RealVal(self.num)


