@dataclass(frozen=True, slots=True)
class Z3OpBridge:
    op: BridgeOp
    arg: Any
    raw: Optional[z3.ExprRef] = None

    def lower(self) -> z3.ExprRef:
        a = lower(self.arg)
        if self.raw is not None:
            return self.raw.decl()(a)
        if self.op in (BridgeOp.F32_TO_BV32, BridgeOp.REAL2BV32, BridgeOp.F32_TO_S32, BridgeOp.F32_TO_U32):
            return z3.Function(self.op.value, z3.RealSort(), z3.BitVecSort(32))(a)
        if self.op in (BridgeOp.BV32_TO_F32, BridgeOp.BV32_TO_REAL, BridgeOp.S32_TO_F32, BridgeOp.U32_TO_F32):
            return z3.Function(self.op.value, z3.BitVecSort(32), z3.RealSort())(a)
        if self.op is BridgeOp.F16_TO_BV16:
            return z3.Function(self.op.value, z3.RealSort(), z3.BitVecSort(16))(a)
        if self.op is BridgeOp.BV16_TO_F16:
            return z3.Function(self.op.value, z3.BitVecSort(16), z3.RealSort())(a)
        if self.op is BridgeOp.F64_TO_BV64:
            return z3.Function(self.op.value, z3.RealSort(), z3.BitVecSort(64))(a)
        return z3.Function(self.op.value, z3.BitVecSort(64), z3.RealSort())(a)


@dataclass(frozen=True, slots=True)
class Z3Other:
    raw: z3.ExprRef

    def lower(self) -> z3.ExprRef:
        return self.raw


Z3Node = Union[
    Z3BvConst,
    Z3RealConst,
    Z3IntConst,
    Z3BoolConst,
    Z3OpExtract,
    Z3OpZeroExt,
    Z3OpSignExt,
    Z3OpConcat,
    Z3OpIte,
    Z3OpEq,
    Z3OpDistinct,
    Z3OpNot,
    Z3OpAnd,
    Z3OpOr,
    Z3OpBvMul,
    Z3OpBvAdd,
    Z3OpBvSub,
    Z3OpBvShl,
    Z3OpBvLShr,
    Z3OpBvAShr,
    Z3OpBvAnd,
    Z3OpBvOr,
    Z3OpBvXor,
    Z3OpBvCmp,
    Z3OpBv2Int,
    Z3OpInt2Bv,
    Z3OpToReal,
    Z3OpToInt,
    Z3OpRealAdd,
    Z3OpRealMul,
    Z3OpRealSub,
    Z3OpRealDiv,
    Z3OpRealNeg,
    Z3OpBridge,
    Z3Other,
]


def view(expr: z3.ExprRef, depth: int = 2) -> Z3Node:
    """Lift a `z3.ExprRef` into a typed `Z3Node` dataclass (O(1) bounded depth)."""
    if isinstance(expr, z3.BitVecNumRef):
        return Z3BvConst(int(expr.as_long()), expr.size(), expr)
    if isinstance(expr, z3.RatNumRef):
        return Z3RealConst(expr.numerator_as_long(), expr.denominator_as_long(), expr)
    if isinstance(expr, z3.IntNumRef):
        return Z3IntConst(expr.as_long(), expr)
    if z3.is_true(expr):
        return Z3BoolConst(True, expr)
    if z3.is_false(expr):
        return Z3BoolConst(False, expr)

    if not z3.is_app(expr):
        return Z3Other(expr)

    decl = expr.decl()
    kind = decl.kind()
    nargs = expr.num_args()

    def sub(e: z3.ExprRef) -> Any:
        if depth > 1:
            return view(e, depth - 1)
        if isinstance(e, z3.BitVecNumRef):
            return Z3BvConst(int(e.as_long()), e.size(), e)
        if isinstance(e, z3.RatNumRef):
            return Z3RealConst(e.numerator_as_long(), e.denominator_as_long(), e)
        if isinstance(e, z3.IntNumRef):
            return Z3IntConst(e.as_long(), e)
        if z3.is_true(e):
            return Z3BoolConst(True, e)
        if z3.is_false(e):
            return Z3BoolConst(False, e)
        return e

    if kind == Z3OpKind.EXTRACT and nargs == 1:
        hi, lo = expr.params()
        return Z3OpExtract(int(hi), int(lo), sub(expr.arg(0)), expr)
    if kind == Z3OpKind.ZERO_EXT and nargs == 1:
        return Z3OpZeroExt(int(expr.params()[0]), sub(expr.arg(0)), expr)
    if kind == Z3OpKind.SIGN_EXT and nargs == 1:
        return Z3OpSignExt(int(expr.params()[0]), sub(expr.arg(0)), expr)
    if kind == Z3OpKind.CONCAT and nargs >= 2:
        return Z3OpConcat(tuple(expr.arg(i) for i in range(nargs)), expr)

    if kind == Z3OpKind.ITE and nargs == 3:
        return Z3OpIte(sub(expr.arg(0)), sub(expr.arg(1)), sub(expr.arg(2)), expr)
    if kind == Z3OpKind.EQ and nargs == 2:
        return Z3OpEq(sub(expr.arg(0)), sub(expr.arg(1)), expr)
    if kind == Z3OpKind.DISTINCT and nargs == 2:
        return Z3OpDistinct(sub(expr.arg(0)), sub(expr.arg(1)), expr)
    if kind == Z3OpKind.NOT and nargs == 1:
        return Z3OpNot(sub(expr.arg(0)), expr)
    if kind == Z3OpKind.AND:
        return Z3OpAnd(tuple(expr.arg(i) for i in range(nargs)), expr)
    if kind == Z3OpKind.OR:
        return Z3OpOr(tuple(expr.arg(i) for i in range(nargs)), expr)

    if kind in _BV_CMP_KIND_TO_OP and nargs == 2:
        return Z3OpBvCmp(_BV_CMP_KIND_TO_OP[kind], sub(expr.arg(0)), sub(expr.arg(1)), expr)

    if nargs == 2 and isinstance(expr, z3.BitVecRef):
        w = expr.size()
        if kind == Z3OpKind.BMUL: return Z3OpBvMul(sub(expr.arg(0)), sub(expr.arg(1)), w, expr)
        if kind == Z3OpKind.BADD: return Z3OpBvAdd(sub(expr.arg(0)), sub(expr.arg(1)), w, expr)
        if kind == Z3OpKind.BSUB: return Z3OpBvSub(sub(expr.arg(0)), sub(expr.arg(1)), w, expr)
        if kind == Z3OpKind.BSHL: return Z3OpBvShl(sub(expr.arg(0)), sub(expr.arg(1)), w, expr)
        if kind == Z3OpKind.BLSHR: return Z3OpBvLShr(sub(expr.arg(0)), sub(expr.arg(1)), w, expr)
        if kind == Z3OpKind.BASHR: return Z3OpBvAShr(sub(expr.arg(0)), sub(expr.arg(1)), w, expr)
        if kind == Z3OpKind.BAND: return Z3OpBvAnd(sub(expr.arg(0)), sub(expr.arg(1)), w, expr)
        if kind == Z3OpKind.BOR: return Z3OpBvOr(sub(expr.arg(0)), sub(expr.arg(1)), w, expr)
        if kind == Z3OpKind.BXOR: return Z3OpBvXor(sub(expr.arg(0)), sub(expr.arg(1)), w, expr)

    if kind == Z3OpKind.BV2INT and nargs == 1:
        return Z3OpBv2Int(sub(expr.arg(0)), expr)
    if kind == Z3OpKind.INT2BV and nargs == 1 and isinstance(expr, z3.BitVecRef):
        return Z3OpInt2Bv(sub(expr.arg(0)), expr.size(), expr)
    if kind == Z3OpKind.TO_REAL and nargs == 1:
        return Z3OpToReal(sub(expr.arg(0)), expr)
    if kind == Z3OpKind.TO_INT and nargs == 1:
        return Z3OpToInt(sub(expr.arg(0)), expr)

    if isinstance(expr, z3.ArithRef) and expr.is_real():
        if kind == Z3OpKind.ADD: return Z3OpRealAdd(tuple(expr.arg(i) for i in range(nargs)), expr)
        if kind == Z3OpKind.MUL: return Z3OpRealMul(tuple(expr.arg(i) for i in range(nargs)), expr)
        if kind == Z3OpKind.SUB and nargs == 2: return Z3OpRealSub(sub(expr.arg(0)), sub(expr.arg(1)), expr)
        if kind == Z3OpKind.DIV and nargs == 2: return Z3OpRealDiv(sub(expr.arg(0)), sub(expr.arg(1)), expr)
        if kind == Z3OpKind.UMINUS and nargs == 1: return Z3OpRealNeg(sub(expr.arg(0)), expr)

    if kind == Z3OpKind.UNINTERPRETED and nargs == 1:
        bop = _BRIDGE_BY_NAME.get(decl.name())
        if bop is not None:
            return Z3OpBridge(bop, sub(expr.arg(0)), expr)

    return Z3Other(expr)


def lift(expr: z3.ExprRef, depth: int = 2) -> Z3Node:
    """Alias for `view(expr, depth)` emphasizing the lift/lower DSL boundary."""
    return view(expr, depth=depth)
